using System.Reflection;
using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ──────────────────────────────────────────────
    //  CalculateTotal – DataRow tests
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(25.00, 2, 0.10, 55.00, DisplayName = "Two items, 10% tax")]
    [DataRow(0.00, 10, 0.20, 0.00, DisplayName = "Zero price yields zero total")]
    [DataRow(99.99, 0, 0.15, 0.00, DisplayName = "Zero quantity yields zero total")]
    [DataRow(100.00, 1, 1.0, 200.00, DisplayName = "100% tax doubles the price")]
    [DataRow(19.99, 3, 0.07, 64.1679, DisplayName = "Fractional tax rate")]
    public void CalculateTotal_WithDataRow_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expectedTotal)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expectedTotal, result);
    }

    // ──────────────────────────────────────────────
    //  CalculateTotal – DynamicData tests
    // ──────────────────────────────────────────────

    public static IEnumerable<object[]> CalculateTotalCases
    {
        get
        {
            yield return [10.00m, 1, 0.0m, 10.00m];
            yield return [10.00m, 5, 0.0m, 50.00m];
            yield return [25.00m, 2, 0.10m, 55.00m];
            yield return [0.01m, 1000, 0.05m, 10.50m];
            yield return [49.95m, 3, 0.08m, 161.838m];
        }
    }

    [TestMethod]
    [DynamicData(nameof(CalculateTotalCases))]
    public void CalculateTotal_WithDynamicData_ReturnsExpected(
        decimal unitPrice, int quantity, decimal taxRate, decimal expectedTotal)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expectedTotal, result);
    }

    // DynamicData from a method source – useful when you need logic to build cases.
    public static IEnumerable<object[]> GetBoundaryCalculateTotalCases()
    {
        yield return [0m, 0, 0m, 0m];          // all zeros
        yield return [decimal.MaxValue / 2, 1, 0m, decimal.MaxValue / 2]; // large price
    }

    [TestMethod]
    [DynamicData(nameof(GetBoundaryCalculateTotalCases), DynamicDataSourceType.Method)]
    public void CalculateTotal_BoundaryCases_ReturnsExpected(
        decimal unitPrice, int quantity, decimal taxRate, decimal expectedTotal)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expectedTotal, result);
    }

    // ──────────────────────────────────────────────
    //  CalculateTotal – invalid input tests
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.0, 1, 0.0, DisplayName = "Negative unit price")]
    [DataRow(10.0, -1, 0.0, DisplayName = "Negative quantity")]
    [DataRow(10.0, 1, -0.1, DisplayName = "Negative tax rate")]
    [DataRow(10.0, 1, 1.1, DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidInput_ThrowsArgumentOutOfRangeException(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ──────────────────────────────────────────────
    //  ApplyDiscount – DataRow tests
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(100.00, 0.0, 100.00, DisplayName = "0% discount leaves price unchanged")]
    [DataRow(100.00, 50.0, 50.00, DisplayName = "50% discount halves the price")]
    [DataRow(100.00, 100.0, 0.00, DisplayName = "100% discount yields zero")]
    [DataRow(79.99, 25.0, 59.9925, DisplayName = "25% off fractional price")]
    [DataRow(200.00, 10.0, 180.00, DisplayName = "10% discount")]
    public void ApplyDiscount_WithDataRow_ReturnsExpected(
        double price, double discountPercent, double expectedPrice)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expectedPrice, result);
    }

    // ──────────────────────────────────────────────
    //  ApplyDiscount – DynamicData tests
    // ──────────────────────────────────────────────

    public static IEnumerable<object[]> ApplyDiscountCases
    {
        get
        {
            yield return [0m, 50m, 0m];         // zero price stays zero
            yield return [250m, 15m, 212.50m];   // standard discount
            yield return [33.33m, 33.33m, 22.22m]; // repeating decimal (truncated)
        }
    }

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountCases))]
    public void ApplyDiscount_WithDynamicData_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expectedPrice)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        // Use tolerance for cases with repeating decimals.
        Assert.IsTrue(Math.Abs(result - expectedPrice) < 0.01m,
            $"Expected ≈{expectedPrice}, got {result}");
    }

    // ──────────────────────────────────────────────
    //  ApplyDiscount – invalid input tests
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(100.0, -1.0, DisplayName = "Negative discount")]
    [DataRow(100.0, 101.0, DisplayName = "Discount above 100%")]
    public void ApplyDiscount_InvalidDiscount_ThrowsArgumentOutOfRangeException(
        double price, double discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent));
    }
}

